        'as': [[0, 'index-11', false]],
        'argument': [[1, 'term-argument', true]],
        'function': [[1, 'term-function', true]],
        'PyObject (C type)': [[0, 'c.PyObject', false]],
        'C++ & <templates>': [[0, 'templates', false]],
        'context manager': [[0, 'context-manager', false]],
      },
    });
  });

  it('finds short indexed terms and preserves their anchors', () => {
    expect(Search.performIndexSearch('as')).toEqual([
      ['reference', 'as', '#index-11', 'Reference', Scorer.indexEntry, 'reference.rst'],
    ]);
    expect(Search.performIndexSearch('for').map(hit => hit[2])).toEqual([
      '#index-6', '#main-for',
    ]);
  });

  it('gives main entries a higher score', () => {
    const hits = Search.performIndexSearch('for');
    expect(hits[1][4]).toBeGreaterThan(hits[0][4]);
    expect(hits[1][4]).toBe(Scorer.mainIndexEntry);
  });

  it('finds glossary and domain entries case-insensitively', () => {
    expect(Search.performIndexSearch('argument')[0][2]).toBe('#term-argument');
    expect(Search.performIndexSearch('function')[0][2]).toBe('#term-function');
    expect(Search.performIndexSearch('  PYOBJECT  ')[0][2]).toBe('#c.PyObject');
  });

  it('matches phrases and punctuation without stemming', () => {
    expect(Search.performIndexSearch('context manager')[0][2]).toBe('#context-manager');
    expect(Search.performIndexSearch('C++')[0][2]).toBe('#templates');
    expect(Search.performIndexSearch('context missing')).toEqual([]);
  });

  it('escapes index entry text for display as HTML', () => {
    expect(Search.performIndexSearch('C++')[0][1]).toBe('C++ &amp; &lt;templates&gt;');
  });

  it('does not return all entries for an empty query', () => {
    expect(Search.performIndexSearch('   ')).toEqual([]);
  });

  it('supports search data generated without index entries', () => {
    delete Search._index.indexentries;
    expect(Search.performIndexSearch('for')).toEqual([]);
  });

  it('supports custom scorers without index entry scores', () => {
    const scorer = Scorer;
    try {
      Scorer = {};
      const hits = Search.performIndexSearch('for');
      expect(Number.isFinite(hits[0][4])).toBe(true);
      expect(hits[1][4]).toBeGreaterThan(hits[0][4]);
    } finally {
      Scorer = scorer;
    }
  });

